#!/usr/bin/env python3
# MEER v4.62 patch (Java) — repo-form ship script.
# Local chain (tasalli-verified) ka repo roop: patch_v462_java
# (single stage). Stage ka source NECHAY VERBATIM embedded hai
# (anchors/asserts bilkul wahi jo local built-v462.java
# (MD5 e702d8c173e8e3bc9737ba8498111670) banane me istemal hue).
# Stage feeding: stage argv leta hai — driver CI target ko temp
# dir me 'built-v455.java' ke naam se deta hai, jis se us ka
# MD5 guard (bfaa8d5c2df68c64ddaa8e1594e9009a) bilkul local chain
# ki tarah fire hota hai (CI me bhi v4.62 steps v4.55 java patch
# ke BAAD chalte hain, is liye anchors isi final content par hain).
# Chalana: repo root se  python3 patch_v462_java.py
# Target: android/app/src/main/java/com/hamza/videomaker/MainActivity.java
# Is version me AndroidManifest ki KOI tabdeeli nahi hai.
#
# FIX (Hamza ke phone ka saboot, 2026-10-26): watermark KABHI ek dafa
# bhi nahi aaya (v4.49-v4.60). Java side: stamp poori video ka dobara
# CPU transcode hai jis par 240s ki waqt-had thi — 3-min 1080p video
# kabhi poori nahi hoti thi -> fail ("encode") -> app chup chaap
# baghair watermark wali video de deta hai. Asal bottleneck:
# copyPlaneCrop/copyPlane/writePlane ki interleaved shakhen har pixel
# par aik ByteBuffer.get/put call karti theen (1080p par har frame
# ~2M slow calls). F1: teeno shakhen bulk + array loop (~10x tez,
# values wohi; writePlane read-modify-write). F2: moving fail par
# STATIC stamp() aik dafa (<120s gate). F3: cap 240s -> 420s (moving
# + static dono). Sab additive; compose ko haath nahi lagaya.
import hashlib
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
JP = ROOT / 'android/app/src/main/java/com/hamza/videomaker/MainActivity.java'

STAGES = [
    ('stage_java.py', '#!/usr/bin/env python3\n# MEER v4.62 JAVA patch — WATERMARK FIX (post-compose stamp ko tez karo +\n# static fallback) — LOCAL ONLY (sim-meer2). GitHub upload / APK build\n# is patch ka kaam NAHI hai.\n#\n# BASE: built-v455.java (MD5 bfaa8d5c2df68c64ddaa8e1594e9009a)\n# — v4.55 Java ki final haalat. Base file kabhi modify NAHI hoti —\n# copy par kaam karke built-v462.java likhi jati hai.\n#\n# MASLA (Hamza ke phone ka saboot, 2026-10-26; main agent ne code se\n# verify kiya): watermark KABHI ek dafa bhi nahi aaya (v4.49-v4.60).\n# JS side sahi hai (toggle default ON, text \'MEER\', fail par banner\n# with reason). Java side masla hai: stamp poori video ka dobara\n# CPU transcode hai (MediaCodec decode -> YUV copy -> overlay ->\n# AVC encode -> mux) jis par 240s ki waqt-had hai (meerSmT0,\n# stampMoveInternal, v4.55) + JS poll ki 4-minute had. 3-minute\n# 1080p video is mein kabhi poori nahi hoti -> fail ("encode") ->\n# app chup chaap baghair watermark wali video de deta hai. Moving\n# stamp pehle chalta hai; static stamp() kabhi try hi nahi hota.\n#\n# COMPOSE-TIME STAMP KYUN NAHI (verify kiya, na ke andaza):\n# RealClipBridge.composeVideo (line 2615+) video ko decode/re-encode\n# NAHI karta — ye MediaExtractor -> MediaMuxer SAMPLE-COPY remux\n# hai (compressed samples seedha muxer me). Is mein overlay lagane\n# ki koi frame-level jagah hai hi nahi; compose ke andar stamp\n# lagana matlab poori compose pipeline ko full transcode me badalna\n# (compose slow + dobara encode se quality girna + audio-sync ka\n# khatra) — ye additive fix NAHI, rewrite hai. Is liye asal fix:\n# post-compose transcode ko ITNA tez karo ke wo window me aa jaye.\n#\n# ASAL BOTTLENECK (verify kiya): copyPlaneCrop / copyPlane /\n# writePlane ki ps!=1 (interleaved) shakhen har pixel par aik\n# ByteBuffer.get(int)/put(int, byte) call karti hain. Asal phone par\n# decoder/encoder ke YUV420Flexible chroma plane aam tor par\n# interleaved hote hain (pixelStride==2), is liye SLOW rasta hi\n# NORMAL rasta hai: 1080p par har frame ~2M slow calls (~40ms+\n# sirf chroma copies) — transcode realtime se slow ho kar 240s\n# cap kha jata hai. Hardware codec tez hai; Java copies deewar thin.\n#\n# FIX (sab additive; kisi maujooda behaviour ki qism NAHI badli):\n#   F1. Teeno slow shakhen bulk + array loop me badlo — values\n#       bilkul wohi (bulk-get ke baad rowBuf[k] = row ke shuru se\n#       k-th byte; purana code bhi yahi absolute position parhta\n#       tha). writePlane me READ-MODIFY-WRITE: U/V aik hi buffer\n#       share karte hain, seedha bulk-put partner ke bytes kuchal\n#       deta — pehle row parh kar partner bytes mehfooz rakho.\n#       Kharab buffer par bulk-op BufferUnderflow/Overflow deta\n#       hai, purana code IndexOutOfBounds — dono RuntimeException,\n#       wohi outer catch (stampMoveInternal: fail="ex:...", static:\n#       return false). Natija: chroma copies ~10x tez; transcode\n#       hardware-codec ki raftaar par aa jata hai (3-min video\n#       ~1-1.5 min me stamp).\n#   F2. startStampMoveAsync ke worker me moving fail par STATIC\n#       stamp() aik dafa try karo — sirf jab moving JALDI fail hua\n#       ho (<120s). 240s+ kharch karke fail hone par JS poll (4 min)\n#       khatam ho chuka hota hai, static dobara bekar hai. Note me\n#       moving ki wajah hamesha rehti hai (banner tak jati hai);\n#       static kamyab ho to note "... +staticok".\n#   F3. Moving cap 240s -> 420s (7 min): JS 2 koshishon me ~8 min\n#       tak poll karta hai (2nd poll usi busy worker ko dekhta\n#       hai), is liye 420s us window ke andar hai aur slow phone\n#       ko bhi mauqa milta hai. Cap ab bhi hai (latak bandhi hui).\n#       Static stampInternal par pehle koi waqt-had NAHI thi — wohi\n#       420s lagayi (warna fallback worker hamesha chalta rehta).\n#\n# BASE NOTE: repo base MainActivity.java (tmp-verify) me\n# MeerMediaBridge hai hi NAHI (anchors wahan 0 hain) — ye patch\n# us par lag hi nahi sakta, bilkul jaise v4.55 ka patch bhi\n# built-v454.java par laga tha, repo base par nahi. CI chain ko\n# Java patches tartib se lagane hain (v450..v455 -> v462), phir\n# compile. Ye patch us chain ki aakhri karri hai.\n#\n# Har anchor exactly-once assert hota hai; aakhir me strip-back\n# proof: saari tabdeeliyan ulta karne par base byte-identical.\n\nimport hashlib\nimport sys\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve().parent\nSRC = Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / \'built-v455.java\'\nDST = Path(sys.argv[2]) if len(sys.argv) > 2 else HERE / \'built-v462.java\'\nassert SRC.resolve() != DST.resolve(), \'SRC aur DST aik nahi ho sakte — patch ROK diya\'\nif SRC.name == \'built-v455.java\':\n    md5 = hashlib.md5(SRC.read_bytes()).hexdigest()\n    assert md5 == \'bfaa8d5c2df68c64ddaa8e1594e9009a\', f\'base MD5 galat: {md5} — patch ROK diya\'\n\nsrc = SRC.read_text(encoding=\'utf-8\')\norig = src\napplied = []\nundo = []\n\n\ndef rep(old, new, label):\n    global src\n    n = src.count(old)\n    assert n == 1, f\'anchor [{label}] {n} dafa mila (1 chahiye tha) — patch ROK diya\'\n    src = src.replace(old, new, 1)\n    applied.append(label)\n    undo.append((new, old))\n\n\n# =====================================================================\n# F1a) copyPlaneCrop — interleaved plane ki per-pixel read -> bulk\n#     row get + array de-interleave (values wohi, ~10x tez).\n# =====================================================================\nCPC_OLD = """            } else {\n                for (int row = 0; row < h; row++) {\n                    for (int col = 0; col < w; col++) {\n                        dst[row * w + col] = buf.get((row + offY) * rs + (col + offX) * ps);\n                    }\n                }\n            }"""\nCPC_NEW = """            } else {\n                // v4.62: BULK chroma copy — interleaved plane (ps==2) par\n                // purana per-byte buf.get() har frame ~1M slow calls karta\n                // tha (1080p chroma), is liye transcode realtime se slow\n                // ho kar 240s cap kha jata tha. Ab poori row aik dafa\n                // bulk-get, phir plain array loop se de-interleave —\n                // values bilkul wohi (rowBuf[k] = row ke shuru se k-th\n                // byte; purana code bhi yahi absolute position parhta\n                // tha), sirf tez. Parhna hai — likhna nahi — is liye\n                // partner bytes ka masla nahi (writePlane me alag hai).\n                int need = offX * ps + (w - 1) * ps + 1;\n                byte[] rowBuf = new byte[need];\n                for (int row = 0; row < h; row++) {\n                    buf.position((row + offY) * rs);\n                    buf.get(rowBuf, 0, need);\n                    int dBase = row * w;\n                    for (int col = 0; col < w; col++) {\n                        dst[dBase + col] = rowBuf[(col + offX) * ps];\n                    }\n                }\n            }"""\nrep(CPC_OLD, CPC_NEW, \'F1a copyPlaneCrop bulk read\')\n\n\n# =====================================================================\n# F1b) copyPlane (static stamp ki read) — wohi bulk tabdeeli.\n# =====================================================================\nCP_OLD = """            } else {\n                for (int row = 0; row < h; row++) {\n                    for (int col = 0; col < w; col++) {\n                        dst[row * w + col] = buf.get(row * rs + col * ps);\n                    }\n                }\n            }"""\nCP_NEW = """            } else {\n                // v4.62: BULK chroma copy (copyPlaneCrop wali wajah) —\n                // static stamp ka parhne wala rasta bhi yahi slow tha.\n                int need = (w - 1) * ps + 1;\n                byte[] rowBuf = new byte[need];\n                for (int row = 0; row < h; row++) {\n                    buf.position(row * rs);\n                    buf.get(rowBuf, 0, need);\n                    int dBase = row * w;\n                    for (int col = 0; col < w; col++) {\n                        dst[dBase + col] = rowBuf[col * ps];\n                    }\n                }\n            }"""\nrep(CP_OLD, CP_NEW, \'F1b copyPlane bulk read\')\n\n\n# =====================================================================\n# F1c) writePlane — interleaved plane ki per-pixel write ->\n#     READ-MODIFY-WRITE bulk (partner bytes mehfooz).\n# =====================================================================\nWP_OLD = """            } else {\n                for (int row = 0; row < h; row++) {\n                    for (int col = 0; col < w; col++) {\n                        buf.put(row * rs + col * ps, src[row * w + col]);\n                    }\n                }\n            }"""\nWP_NEW = """            } else {\n                // v4.62: BULK chroma write — READ-MODIFY-WRITE: interleaved\n                // plane (ps==2) me U/V aik hi buffer share karte hain;\n                // seedha bulk-put partner ke bytes kuchal deta (pehle\n                // row bulk-parh kar partner bytes mehfooz rakho, phir\n                // sirf apni strided positions badlo, phir bulk-put).\n                // Purane per-byte absolute put jaisi hi values, ~10x tez.\n                int need = (w - 1) * ps + 1;\n                byte[] rowBuf = new byte[need];\n                for (int row = 0; row < h; row++) {\n                    buf.position(row * rs);\n                    buf.get(rowBuf, 0, need);\n                    int sBase = row * w;\n                    for (int col = 0; col < w; col++) {\n                        rowBuf[col * ps] = src[sBase + col];\n                    }\n                    buf.position(row * rs);\n                    buf.put(rowBuf, 0, need);\n                }\n            }"""\nrep(WP_OLD, WP_NEW, \'F1c writePlane bulk read-modify-write\')\n\n\n# =====================================================================\n# F2) startStampMoveAsync worker — moving fail par STATIC stamp()\n#     aik dafa, sirf jab moving jaldi fail hua ho (<120s).\n# =====================================================================\nWK_OLD = """                    try {\n                        String r = stampMoving(videoPath, text);\n                        if (r != null && r.startsWith("ok:")) {\n                            meerStampMoveResult = r.substring(3);\n                        } else {\n                            meerStampMoveNote = (r == null) ? "null" : r;\n                            meerStampMoveResult = videoPath;\n                        }\n                        meerStampMoveState = "done";"""\nWK_NEW = """                    try {\n                        // v4.62: moving fail par STATIC fallback — JS sirf\n                        // moving wala async janta hai, is liye static aaj\n                        // tak kabhi try hi nahi hua. Sirf tab jab moving\n                        // JALDI fail hua ho (<120s): 240s+ kharch karke\n                        // fail hone par JS poll (4 min) khatam ho chuka\n                        // hota hai, static dobara shuru karna bekar hai.\n                        long meerWmT0 = System.currentTimeMillis();\n                        String r = stampMoving(videoPath, text);\n                        if (r != null && r.startsWith("ok:")) {\n                            meerStampMoveResult = r.substring(3);\n                        } else {\n                            String movReason = (r == null) ? "null" : r;\n                            meerStampMoveNote = movReason;\n                            meerStampMoveResult = videoPath;\n                            if (System.currentTimeMillis() - meerWmT0 < 120000) {\n                                try {\n                                    String r2 = stamp(videoPath, text);\n                                    if (r2 != null && !r2.equals(videoPath)\n                                            && r2.endsWith("-wm.mp4")) {\n                                        java.io.File f2 = new java.io.File(r2);\n                                        if (f2.exists() && f2.length() > 10000) {\n                                            meerStampMoveResult = r2;\n                                            meerStampMoveNote = movReason + "+staticok";\n                                        }\n                                    }\n                                } catch (Throwable ignored) {}\n                            }\n                        }\n                        meerStampMoveState = "done";"""\nrep(WK_OLD, WK_NEW, \'F2 moving worker static fallback\')\n\n\n# =====================================================================\n# F3a) stampMoveInternal cap 240s -> 420s (JS 2 koshishon me ~8 min\n#      tak poll karta hai; 420s us window ke andar, slow phone ko\n#      bhi mauqa; cap ab bhi hai — latak bandhi hui).\n# =====================================================================\nrep(\'                while (!encDone && fail == null && guard++ < 300000 && (System.currentTimeMillis() - meerSmT0) < 240000) {\',\n    \'                while (!encDone && fail == null && guard++ < 300000 && (System.currentTimeMillis() - meerSmT0) < 420000) { // v4.62: 240s->420s\',\n    \'F3a stamp-move cap 420s\')\n\n\n# =====================================================================\n# F3b) stampInternal — apna t0 (anchor: OverlayData wali jorri,\n#      file me aik hi dafa hai).\n# =====================================================================\nST_OLD = """                byte[] tightY = null, tightU = null, tightV = null;\n                OverlayData ov = null;"""\nST_NEW = """                byte[] tightY = null, tightU = null, tightV = null;\n                OverlayData ov = null;\n                long meerStT0 = System.currentTimeMillis(); // v4.62: static stamp ki bhi waqt-had (moving jaisi)"""\nrep(ST_OLD, ST_NEW, \'F3b static stamp t0\')\n\n\n# =====================================================================\n# F3c) stampInternal loop par wohi 420s had.\n# =====================================================================\nrep(\'                while (!encDone && guard++ < 300000) {\',\n    \'                while (!encDone && guard++ < 300000 && (System.currentTimeMillis() - meerStT0) < 420000) {\',\n    \'F3c static stamp loop 420s cap\')\n\n\n# ---------- Aakhri asserts ----------\nassert src.count(\'buf.get((row + offY) * rs + (col + offX) * ps)\') == 0, \'purana copyPlaneCrop slow loop bacha\'\nassert src.count(\'buf.get(row * rs + col * ps)\') == 0, \'purana copyPlane slow loop bacha\'\nassert src.count(\'buf.put(row * rs + col * ps, src[row * w + col])\') == 0, \'purana writePlane slow loop bacha\'\nassert src.count(\'byte[] rowBuf = new byte[need];\') == 3, \'bulk rowBuf 3 jagah (F1a/F1b/F1c)\'\nassert src.count(\'meerWmT0\') == 2, \'meerWmT0: decl 1 + elapsed check 1\'\nassert src.count(\'movReason + "+staticok"\') == 1, \'static-ok note aik dafa\'\nassert src.count(\'meerStT0\') == 2, \'meerStT0: decl 1 + static loop 1\'\nassert src.count(\'< 420000)\') == 2, \'420s cap 2 loops (moving + static)\'\nassert src.count(\'(System.currentTimeMillis() - meerSmT0) < 240000\') == 0, \'purana 240s cap bacha\'\nassert src.count(\'while (!encDone && guard++ < 300000) {\') == 0, \'purana static loop bacha\'\nassert src.count(\'while (!encDone && fail == null && guard++ < 300000 && (System.currentTimeMillis() - meerSmT0) < 420000)\') == 1, \'moving loop naya form\'\nassert src.count(\'while (!encDone && guard++ < 300000 && (System.currentTimeMillis() - meerStT0) < 420000)\') == 1, \'static loop naya form\'\nassert src.count(\'public String stampMoving(\') == orig.count(\'public String stampMoving(\') == 1\nassert src.count(\'private boolean stampInternal(\') == orig.count(\'private boolean stampInternal(\') == 1\nassert src.count(\'private String stampMoveInternal(\') == orig.count(\'private String stampMoveInternal(\') == 1\nassert src.count(\'public String stamp(String videoPath, String text)\') == orig.count(\'public String stamp(String videoPath, String text)\') == 1\nassert src.count(\'public String startStampMoveAsync(\') == orig.count(\'public String startStampMoveAsync(\') == 1\nassert src.count(\'private void copyPlaneCrop(\') == orig.count(\'private void copyPlaneCrop(\') == 1\nassert src.count(\'private void copyPlane(\') == orig.count(\'private void copyPlane(\') == 1\nassert src.count(\'private void writePlane(\') == orig.count(\'private void writePlane(\') == 1\nassert src.count(\'private void imageToTightCrop(\') == orig.count(\'private void imageToTightCrop(\') == 1\nassert src.count(\'private void imageToTight(\') == orig.count(\'private void imageToTight(\') == 1\nassert src.count(\'private void tightToImage(\') == orig.count(\'private void tightToImage(\') == 1\nassert src.count(\'private BandOverlay makeBandOverlay(\') == orig.count(\'private BandOverlay makeBandOverlay(\') == 1\nassert src.count(\'private OverlayData makeOverlay(\') == orig.count(\'private OverlayData makeOverlay(\') == 1\n# Braces/parens balance base ke mutabiq symmetric hona chahiye\nassert src.count(\'{\') - src.count(\'}\') == orig.count(\'{\') - orig.count(\'}\'), \'brace balance badla\'\nassert src.count(\'(\') - src.count(\')\') == orig.count(\'(\') - orig.count(\')\'), \'paren balance badla\'\n# Strip-back proof: saari tabdeeliyan ulta karne par base wapas\nchk = src\nfor new, old in reversed(undo):\n    assert chk.count(new) >= 1, f\'strip-back: naya hissa nahi mila: {new[:60]}\'\n    chk = chk.replace(new, old, 1)\nassert chk == orig, \'strip-back FAIL — tabdeeli ke ilawa bhi kuch badla\'\n\nDST.write_text(src, encoding=\'utf-8\')\nprint(\'applied:\', \', \'.join(applied))\nprint(\'WROTE\', DST, f\'({len(src)} chars; base se {len(src) - len(orig):+d})\')\nprint(\'MD5:\', hashlib.md5(DST.read_bytes()).hexdigest())\n'),
]

def run_stage(tmp, name, source, args=(), cwd=None):
    f = tmp / name
    f.write_text(source, encoding='utf-8')
    print(f'--- v4.62 stage {name} ---', flush=True)
    subprocess.run([sys.executable, str(f), *[str(a) for a in args]],
                   cwd=str(cwd or tmp), check=True)

def main():
    assert JP.is_file(), f'target nahi mila: {JP} — patch ROK diya'
    original = JP.read_bytes()
    with tempfile.TemporaryDirectory() as td:
        tmp = Path(td)
        stages = dict(STAGES)
        # Stage: java — argv SRC/DST; SRC ka naam 'built-v455.java'
        # hote hi us ka MD5 guard fire hoga.
        (tmp / 'built-v455.java').write_bytes(original)
        run_stage(tmp, 'stage_java.py', stages['stage_java.py'],
                  (tmp / 'built-v455.java', tmp / 'built-v462.java'))
        final = (tmp / 'built-v462.java').read_bytes()
    fmd5 = hashlib.md5(final).hexdigest()
    assert fmd5 == 'e702d8c173e8e3bc9737ba8498111670', \
        f'final MD5 galat: {fmd5} — patch ROK diya (kuch nahi likha)'
    JP.write_bytes(final)
    print(f'v4.62 java patch done: {JP} ({len(original)} -> {len(final)} bytes)')


if __name__ == '__main__':
    main()
